CREATE TABLE IF NOT EXISTS gis_phase357_dataset_semantics (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), source_id TEXT NOT NULL UNIQUE, provider TEXT, feature_count BIGINT NOT NULL DEFAULT 0, state_count BIGINT NOT NULL DEFAULT 0, parent_count BIGINT NOT NULL DEFAULT 0, feature_key_count BIGINT NOT NULL DEFAULT 0, valid_geometry_count BIGINT NOT NULL DEFAULT 0, mean_bbox_area DOUBLE PRECISION, min_bbox_area DOUBLE PRECISION, max_bbox_area DOUBLE PRECISION, semantic_class TEXT NOT NULL, confidence DOUBLE PRECISION NOT NULL DEFAULT 0, evidence JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now());